/* @lc app=leetcode id=3965 lang=kotlin */ class Solution { fun finishTime(n: Int, edges: Array<IntArray>, baseTime: IntArray): Long = edges.groupBy({ it[0] }, { it[1] }).let { g -> generateSequence(listOf(0)) { f -> f.flatMap { g[it].orEmpty() }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> LongArray(n).also { fin -> order.forEach { v -> g[v].orEmpty().let { ch -> fin[v] = if (ch.isEmpty()) baseTime[v].toLong() else ch.map { fin[it] }.let { fs -> fs.max().let { lat -> lat + (lat - fs.min()) + baseTime[v] } } } } }[0] } } }